#!/usr/bin/env node
/**
 * SBOM validation for Oxyide Forge (M5.8).
 *
 * Validates the CycloneDX JSON bill of materials generated by
 * `npm run security:sbom` (cyclonedx-npm, lockfile-derived):
 *   1. file exists and parses as JSON;
 *   2. bomFormat is CycloneDX with a supported spec version;
 *   3. application metadata matches package.json (name + version);
 *   4. every direct production dependency from package.json is present
 *      (matched by purl, which carries the full scoped name);
 *   5. component count is sane (guards against empty/truncated output);
 *   6. no secret-shaped values appear anywhere in the SBOM text.
 *
 * Usage: node scripts/sbom-validate.cjs [path-to-sbom]
 * Exit codes: 0 = valid; 1 = invalid; 2 = infrastructure failure.
 */
'use strict';

const fs = require('fs');
const path = require('path');

function fail(message) {
  process.stdout.write(`SBOM validation FAIL: ${message}\n`);
  process.exit(1);
}

function failClosed(message) {
  process.stdout.write(`SBOM validation ERROR: ${message}\n`);
  process.exit(2);
}

const ROOT = path.resolve(__dirname, '..');
const sbomPath = process.argv[2] || path.join(ROOT, 'sbom.cyclonedx.json');

let raw;
try {
  raw = fs.readFileSync(sbomPath, 'utf8');
} catch (error) {
  failClosed(`cannot read SBOM file ${sbomPath}: ${error instanceof Error ? error.message : String(error)}`);
}

let bom;
try {
  bom = JSON.parse(raw);
} catch (error) {
  fail(`SBOM is not valid JSON: ${error instanceof Error ? error.message : String(error)}`);
}

let pkg;
try {
  pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
} catch (error) {
  failClosed(`cannot read package.json: ${error instanceof Error ? error.message : String(error)}`);
}

// 2. Format.
if (bom.bomFormat !== 'CycloneDX') {
  fail(`bomFormat is ${JSON.stringify(bom.bomFormat)}, expected "CycloneDX"`);
}
if (typeof bom.specVersion !== 'string' || !/^1\.[5-9]/.test(bom.specVersion)) {
  fail(`unsupported specVersion ${JSON.stringify(bom.specVersion)} (expected CycloneDX 1.5+)`);
}

// 3. Application metadata.
const component = (bom.metadata && bom.metadata.component) || {};
if (component.name !== pkg.name || component.version !== pkg.version) {
  fail(
    `application metadata mismatch: SBOM has ${JSON.stringify(component.name)}@${JSON.stringify(component.version)}, package.json has ${JSON.stringify(pkg.name)}@${JSON.stringify(pkg.version)}`,
  );
}

// 4 + 5. Dependency inventory.
const components = Array.isArray(bom.components) ? bom.components : [];
if (components.length < 10) {
  fail(`component count ${components.length} is implausibly small (expected the full lockfile tree)`);
}
const purls = new Set(
  components.map((c) => (c && typeof c.purl === 'string' ? c.purl : '')).filter(Boolean),
);
const directDeps = Object.keys(pkg.dependencies || {});
const missing = directDeps.filter((dep) => {
  const scoped = `pkg:npm/%40${dep.slice(1)}@`;
  const bare = `pkg:npm/${dep}@`;
  for (const purl of purls) {
    if (purl.startsWith(scoped) || purl.startsWith(bare)) return false;
  }
  return true;
});
if (missing.length > 0) {
  fail(`direct dependencies missing from SBOM: ${missing.join(', ')}`);
}

// 6. No secret-shaped values in supply-chain metadata.
const SECRET_PATTERN = /(JWT_SECRET|DATABASE_URL|REDIS_URL|BEGIN [A-Z ]*PRIVATE KEY|ghp_[A-Za-z0-9]{8,}|sk-live-)/;
if (SECRET_PATTERN.test(raw)) {
  fail('SBOM text contains secret-shaped values');
}

process.stdout.write(
  `SBOM validation PASS: CycloneDX ${bom.specVersion}, ${pkg.name}@${pkg.version}, ${components.length} components, ${directDeps.length}/${directDeps.length} direct dependencies present, no secrets.\n`,
);
process.exit(0);
